const visual = {
  prepare: function (input) {
    var out = [];
    for (var i = -5; i <= 5; i++) {
      out.push({ kind: 'text', payload: String(i) });
    }
    return out;
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = 60;
    var x1 = w - 60;
    var cy = Math.round(h * 0.5);
    var axisCmds = visualSdk.axis({ x0: x0, y0: cy, x1: x1, y1: cy, ticks: 11, tickLength: 10 });
    var children = [
      { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } }
    ];
    for (var i = 0; i < 11; i++) {
      var x = x0 + (x1 - x0) * i / 10;
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: cy + 16 },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'number-line',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [{ id: 'axis', commands: axisCmds }],
      root: { type: 'group', children: children }
    };
  }
};
